# owner: platform
"""Plain text absence notices for parents."""

from typing import Iterable, List

from rosterkit.models import Mark, Student
from datetime import date


def _check_owner(student: Student, marks: List[Mark]) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(f"mark for {mark.student_id} given for {student.student_id}")


def _absent_days(marks: List[Mark]) -> List[date]:
    return sorted({mark.day for mark in marks if mark.status == "absent"})


# ---
def build_absence_notice(student: Student, marks: Iterable[Mark]) -> str:
    """Short notice naming the student, days missed and the dates in order."""
    mark_list = list(marks)
    _check_owner(student, mark_list)
    days = _absent_days(mark_list)
    if not days:
        raise ValueError(f"no absences for {student.student_id}")
    name = f"{student.first_name} {student.last_name}"
    dates = "\n".join(f"- {day.isoformat()}" for day in days)
    return f"{name} missed {len(days)} day(s) of school:\n{dates}"
